#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        // new = p[n-y..n-1] + p[x..n-y-1] + p[0..x-1]
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    for(int t=0; t<n-2; t++){
        int pos = -1;
        for(int i=0;i<n;i++) if(p[i]==t+1){ pos=i; break; }
        if(pos==t) continue;

        int rem = n - t; // remaining elements to sort (positions t..n-1)
        // Element is at position pos (pos >= t), needs to go to position t
        // First move element to position t using at most 2 ops

        if(pos == n-1){
            // op(t+1, 1): new puts p[n-1] at front, then p[t+1..n-2], then p[0..t]
            // p[n-1] goes to position 0. Already sorted prefix p[0..t-1] goes to end.
            // We need x=1, y=n-1-pos... let me just use op(t+1,1) if valid
            if(t+1+1 < n){
                do_op(t+1, 1);
                // Now p[0..t-1] which was sorted is at the end. But element t+1 is at position 0=t? No, at position 0.
                // Hmm, this messes up already sorted elements. 
            }
        }
        // Let me just use: move to position n-1 first with op(1, n-1-pos), then move to t with op(t, 1)
        pos = -1;
        for(int i=0;i<n;i++) if(p[i]==t+1){ pos=i; break; }
        if(pos==t) continue;
        if(pos!=n-1 && pos>t){
            int y=n-1-pos;
            if(y>=1 && t+1+y<n){ do_op(t+1,y); pos=-1; for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;} }
        }
        if(pos==t) continue;
        if(pos>t && t+1>=1 && n-pos>=1 && t+1+n-pos<n){ do_op(t+1, n-pos); }
        else if(pos==n-1 && t+1>=1 && 1+t+1<n){ do_op(t+1, 1); }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
